import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"strings"
)

func main() {
	root := "/bench/repo"
	fset := token.NewFileSet()
	var results []string
	skip := map[string]bool{"web": true, ".git": true}
	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil { return err }
		if info.IsDir() {
			if skip[info.Name()] { return filepath.SkipDir }
			return nil
		}
		if !strings.HasSuffix(path, ".go") { return nil }
		if strings.Contains(path, "/web/") { return nil }
		file, err := parser.ParseFile(fset, path, nil, 0)
		if err != nil { return nil }
		for _, decl := range file.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok || fn.Recv == nil || fn.Name.Name != "Close" { continue }
			recv := fn.Recv.List[0].Type
			recvStr := "?"
			switch t := recv.(type) {
			case *ast.StarExpr:
				if id, ok := t.X.(*ast.Ident); ok { recvStr = "*" + id.Name }
			case *ast.Ident:
				recvStr = t.Name
			}
			results = append(results, fmt.Sprintf("%s:%d recv=%s test=%v", path, fset.Position(fn.Pos()).Line, recvStr, strings.HasSuffix(path, "_test.go")))
		}
		return nil
	})
	if err != nil { fmt.Fprintf(os.Stderr, "walk err: %v\n", err) }
	fmt.Printf("Total Close methods: %d\n", len(results))
	for _, r := range results { fmt.Println(r) }
}
GO

